def _search(self, searchstring):
        """ search users
        @str searchstring: search string
        @rtype: dict, {<user>: {<attr>: <value>}}
        """
        if not searchstring:
            return {}
        searchstring = searchstring.lower()
        users = {}
        for user in self.users:
            if searchstring in user.lower():
                users[user] = self.users[user]
        return users

